  doll:null,
  lesson:{q:{be:["Чаму Прадслава адмовілася ад шлюбу?","Што такое скрыпторый і чаму перапісванне кніг было важнай справай?","Што здарылася з крыжам Еўфрасінні?"],ru:["Почему Предслава отказалась от замужества?","Что такое скрипторий и почему переписывание книг было важным делом?","Что случилось с крестом Евфросинии?"]},
          task:{be:["Знайдзіце на карце Беларусі Полацк і вызначце, колькі кіламетраў да вашага горада.","Намалюйце крыж Еўфрасінні і падпішыце, што азначаюць яго часткі."],ru:["Найдите на карте Беларуси Полоцк и определите, сколько километров до вашего города.","Нарисуйте крест Евфросинии и подпишите, что означают его части."]}}
